#!/usr/bin/env python3
"""Deterministic C99 catalogues from share/providers.json (the single source).

Writes kbd/providers.inc (on-board UI) and agent/src/web_providers.inc (usb0 web).
--check never changes generated files and fails if either is stale.
"""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
KBD = ROOT / 'kbd/providers.inc'
WEB = ROOT / 'agent/src/web_providers.inc'


def catalogue():
    return json.loads((ROOT / 'share/providers.json').read_text(encoding='utf-8'))['providers']


def q(s):
    return json.dumps(s, ensure_ascii=False)


def generate():
    ps = catalogue()
    rows = ['/* Generated by tools/gen-providers.py; edit share/providers.json. */']
    for n, p in enumerate(ps):
        rows.append(f'static const ui_model_t models_{n}[] = {{')
        rows.extend('    {%s, %d, %d},' % (q(m['id']), m['vision'], m['tools']) for m in p['models'])
        rows.append('};')
    rows.append('const ui_provider_t UI_PROVIDERS[] = {')
    rows.extend('    {%s, %s, %s, %d, %d, models_%d, %d},' %
                (q(p['id']),q(p['label']),q(p['base_url']),p['domestic'],p['adapter']=='openai',n,len(p['models'])) for n,p in enumerate(ps))
    rows.extend(['};', 'const size_t UI_PROVIDER_COUNT = sizeof UI_PROVIDERS / sizeof UI_PROVIDERS[0];', ''])
    return '\n'.join(rows)


def generate_web():
    """Same rows for mk20-agent --web: file-local tables, web_* types (web_store.c)."""
    ps = catalogue()
    rows = ['/* Generated by tools/gen-providers.py; edit share/providers.json. */']
    for n, p in enumerate(ps):
        rows.append(f'static const web_model_t web_models_{n}[] = {{')
        rows.extend('    {%s, %d, %d},' % (q(m['id']), m['vision'], m['tools']) for m in p['models'])
        rows.append('};')
    rows.append('static const web_provider_t WEB_PROVIDERS[] = {')
    rows.extend('    {%s, %s, %s, %d, %d, web_models_%d, %d},' %
                (q(p['id']),q(p['label']),q(p['base_url']),p['domestic'],p['adapter']=='openai',n,len(p['models'])) for n,p in enumerate(ps))
    rows.extend(['};', '#define WEB_PROVIDER_COUNT (sizeof WEB_PROVIDERS / sizeof WEB_PROVIDERS[0])', ''])
    return '\n'.join(rows)


if __name__ == '__main__':
    ap = argparse.ArgumentParser(); ap.add_argument('--check', action='store_true'); args = ap.parse_args()
    outputs = ((KBD, generate()), (WEB, generate_web()))
    if args.check:
        stale = [str(p.relative_to(ROOT)) for p, text in outputs
                 if not p.exists() or p.read_text(encoding='utf-8') != text]
        if stale:
            raise SystemExit(f'{", ".join(stale)} stale: run python3 deck/tools/gen-providers.py')
    else:
        for p, text in outputs:
            p.write_text(text, encoding='utf-8')
